**Change 1: Early Taint Validation in function_call**
<enforcement spec="HS-SEC-001">
<location>ext/fiddle/function.c, function_call()</location>
<diff>
    TypedData_Get_Struct(self, ffi_cif, &function_data_type, cif);

+   if (rb_safe_level() >= 1) {
+       for (i = 0; i < argc; i++) {
+           VALUE src = argv[i];
+           if (OBJ_TAINTED(src)) {
+               rb_raise(rb_eSecurityError, "tainted parameter not allowed");
