**Change 3: Safe Data Return with Bounds Checking**
<enforcement spec="HS-MEM-003">
<location>libvncserver/websockets.c, hybiReturnData()</location>
<diff>
-/* Original: Direct memcpy without proper bounds checking */
-if (wsctx->readlen > len) {
-    memcpy(dst, wsctx->readbuf + wsctx->readbufstart, len);
-    result = len;
-    wsctx->readbuflen -= len;
-    wsctx->readbufstart += len;
-} else {
-    memcpy(dst, wsctx->readbuf + wsctx->readbufstart, wsctx->readbuflen);
-    result = wsctx->readbuflen;
-    wsctx->readbuflen = 0;
-    wsctx->readbufstart = 0;
-}
-
+/* Fixed: Structured data return with state tracking */
+if (wsctx->readlen > 0) {
+    /* simply return what we have */
+    if (wsctx->readlen > len) {
+        rfbLog("copy to %d bytes to dst buffer; readPos=%p, readLen=%d\n", 
+               len, wsctx->readPos, wsctx->readlen);
+        memcpy(dst, wsctx->readPos, len);
+        *nWritten = len;
+        wsctx->readlen -= len;
+        wsctx->readPos += len;
+        nextState = WS_HYBI_STATE_DATA_AVAILABLE;
+    } else {
+        rfbLog("copy to %d bytes to dst buffer; readPos=%p, readLen=%d\n", 
+               wsctx->readlen, wsctx->readPos, wsctx->readlen);
+        memcpy(dst, wsctx->readPos, wsctx->readlen);
+        *nWritten = wsctx->readlen;
+        wsctx->readlen = 0;
+        wsctx->readPos = NULL;
+        if (hybiRemaining(wsctx) == 0) {
