+				/* too many compression pointers */
+				*to = 0; /* end the result prematurely */
+				return;
+			}
 			/* follow pointer */
 			dname = sldns_buffer_at(pkt, PTR_OFFSET(lablen, *dname));
 			lablen = *dname++;
 			continue;
 		}
 		if(lablen > LDNS_MAX_LABELLEN) {
 			*to = 0; /* end the result prematurely */
 			return;
 		}
 		log_assert(lablen <= LDNS_MAX_LABELLEN);
